textOptions.schema:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "GuardrailSecurityResult",
  "type": "object",
  "properties": {
    "is_safe": {
      "type": "boolean",
      "description": "True, если промпт безопасен. False, если обнаружена попытка взлома."
    },
    "confidence": {
      "type": "number",
      "description": "Уверенность модели в оценке от 0.0 до 1.0."
    },
    "risk_category": {
      "type": "string",
      "enum": [
        "none",
        "instruction_override",
        "jailbreak_attempt",
        "role_manipulation",
        "payload_splitting",
        "potential_threat"
      ],
      "description": "Категория обнаруженной атаки."
    },
    "reasoning": {
      "type": "string",
      "description": "Краткое обоснование того, почему промпт был помечен как опасный."
    }
  },
  "required": ["is_safe", "confidence", "risk_category", "reasoning"],
  "additionalProperties": false
}

parameters.jsCode:
const text = $input.first().json.text;
const parsed = JSON.parse(text);
return [{ json: parsed }];
